CREATE TABLE confsys.competitions(id uuid PRIMARY KEY,version integer NOT NULL CHECK(version>0),current_rubric_id uuid,award_draft jsonb NOT NULL DEFAULT '[]',award_reason text NOT NULL DEFAULT '',active_publication_id uuid);
CREATE TABLE confsys.competition_rubrics(id uuid PRIMARY KEY,competition_id uuid NOT NULL REFERENCES confsys.competitions(id),version integer NOT NULL CHECK(version>0),document jsonb NOT NULL,created_by uuid NOT NULL REFERENCES confsys.users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(competition_id,version),UNIQUE(id,competition_id));
ALTER TABLE confsys.competitions ADD CONSTRAINT competition_current_rubric FOREIGN KEY(current_rubric_id,id) REFERENCES confsys.competition_rubrics(id,competition_id);
CREATE TABLE confsys.competition_entries(id uuid PRIMARY KEY,competition_id uuid NOT NULL REFERENCES confsys.competitions(id),submission_id uuid NOT NULL REFERENCES confsys.submissions(id),revision_id uuid NOT NULL,owner_id uuid NOT NULL REFERENCES confsys.users(id),version integer NOT NULL DEFAULT 1,state text NOT NULL CHECK(state IN('requested','approved','rejected','withdrawn','disqualified')),title text NOT NULL,presenter_name text NOT NULL,reason text NOT NULL DEFAULT '',FOREIGN KEY(revision_id,submission_id) REFERENCES confsys.submission_revisions(id,submission_id),UNIQUE(competition_id,submission_id),UNIQUE(id,competition_id),FOREIGN KEY(submission_id,owner_id) REFERENCES confsys.submissions(id,owner_id));
CREATE TABLE confsys.competition_assignments(id uuid PRIMARY KEY,entry_id uuid NOT NULL REFERENCES confsys.competition_entries(id),competition_id uuid NOT NULL REFERENCES confsys.competitions(id),judge_id uuid NOT NULL REFERENCES confsys.users(id),rubric_id uuid NOT NULL REFERENCES confsys.competition_rubrics(id),version integer NOT NULL DEFAULT 1,state text NOT NULL DEFAULT 'assigned' CHECK(state IN('assigned','submitted','conflicted','cancelled')),document jsonb NOT NULL DEFAULT '{"scores":[],"comment":""}',UNIQUE(entry_id,judge_id),FOREIGN KEY(entry_id,competition_id) REFERENCES confsys.competition_entries(id,competition_id),FOREIGN KEY(rubric_id,competition_id) REFERENCES confsys.competition_rubrics(id,competition_id));
CREATE TABLE confsys.competition_conflicts(entry_id uuid NOT NULL REFERENCES confsys.competition_entries(id),competition_id uuid NOT NULL REFERENCES confsys.competitions(id),judge_id uuid NOT NULL REFERENCES confsys.users(id),reason text NOT NULL,PRIMARY KEY(entry_id,judge_id));
CREATE TABLE confsys.competition_scores(id uuid PRIMARY KEY,assignment_id uuid NOT NULL UNIQUE REFERENCES confsys.competition_assignments(id),document jsonb NOT NULL,points integer NOT NULL CHECK(points>=0),maximum integer NOT NULL CHECK(maximum>0 AND points<=maximum),submitted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE confsys.competition_publications(id uuid PRIMARY KEY,competition_id uuid NOT NULL REFERENCES confsys.competitions(id),source_version integer NOT NULL,document jsonb NOT NULL,published_by uuid NOT NULL REFERENCES confsys.users(id),published_at timestamptz NOT NULL DEFAULT now(),UNIQUE(competition_id,source_version),UNIQUE(id,competition_id));
ALTER TABLE confsys.competitions ADD CONSTRAINT competition_current_publication FOREIGN KEY(active_publication_id,id) REFERENCES confsys.competition_publications(id,competition_id);
GRANT SELECT,INSERT ON confsys.competitions,confsys.competition_rubrics,confsys.competition_entries,confsys.competition_assignments,confsys.competition_conflicts,confsys.competition_scores,confsys.competition_publications TO confsys_app;
GRANT UPDATE(version,current_rubric_id,award_draft,award_reason,active_publication_id) ON confsys.competitions TO confsys_app;
GRANT UPDATE(version,state,reason) ON confsys.competition_entries TO confsys_app;
GRANT UPDATE(version,state,document) ON confsys.competition_assignments TO confsys_app;
CREATE INDEX competition_entries_owner ON confsys.competition_entries(owner_id,competition_id);
CREATE INDEX competition_assignments_judge ON confsys.competition_assignments(judge_id,state);
-- Immutable rubrics, final score records, and award snapshots have no runtime UPDATE/DELETE grants.
ALTER TABLE confsys.competition_assignments ENABLE ROW LEVEL SECURITY;
ALTER TABLE confsys.competition_assignments FORCE ROW LEVEL SECURITY;
CREATE POLICY competition_assignments_actor ON confsys.competition_assignments TO confsys_app USING(current_setting('app.competitions_manage',true)='true' OR judge_id=nullif(current_setting('app.actor_id',true),'')::uuid) WITH CHECK(current_setting('app.competitions_manage',true)='true' OR judge_id=nullif(current_setting('app.actor_id',true),'')::uuid);
CREATE POLICY competition_assignments_operator ON confsys.competition_assignments TO confsys_migrator USING(true) WITH CHECK(true);
ALTER TABLE confsys.competition_scores ENABLE ROW LEVEL SECURITY;
ALTER TABLE confsys.competition_scores FORCE ROW LEVEL SECURITY;
CREATE POLICY competition_scores_actor ON confsys.competition_scores TO confsys_app USING(current_setting('app.competitions_manage',true)='true' OR EXISTS(SELECT 1 FROM confsys.competition_assignments a WHERE a.id=assignment_id AND a.judge_id=nullif(current_setting('app.actor_id',true),'')::uuid)) WITH CHECK(current_setting('app.competitions_manage',true)='true' OR EXISTS(SELECT 1 FROM confsys.competition_assignments a WHERE a.id=assignment_id AND a.judge_id=nullif(current_setting('app.actor_id',true),'')::uuid));
CREATE POLICY competition_scores_operator ON confsys.competition_scores TO confsys_migrator USING(true) WITH CHECK(true);

ALTER TABLE confsys.competition_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE confsys.competition_entries FORCE ROW LEVEL SECURITY;
CREATE POLICY competition_entries_actor ON confsys.competition_entries TO confsys_app USING(current_setting('app.competitions_manage',true)='true' OR owner_id=nullif(current_setting('app.actor_id',true),'')::uuid OR EXISTS(SELECT 1 FROM confsys.competition_assignments a WHERE a.entry_id=confsys.competition_entries.id AND a.judge_id=nullif(current_setting('app.actor_id',true),'')::uuid)) WITH CHECK(current_setting('app.competitions_manage',true)='true' OR owner_id=nullif(current_setting('app.actor_id',true),'')::uuid);
CREATE POLICY competition_entries_operator ON confsys.competition_entries TO confsys_migrator USING(true) WITH CHECK(true);
